Translate("ruRU", "vol-jin", {
	title = "Вол'джин",
	subtitle = "Вождь племени Черного Копья",
	found = "Крепость Громмаша, рядом с вождем Орды",
	hint = [=[Поговорите с троллем, который стоит рядом с вождем в Крепости Громмаша.]=],
	allegiance = "Орда · Племя Черного Копья",
	sections = {
		{
			title = "Обзор",
			text = [=[Вол'джин — вождь {link:darkspear-trolls}племени Черного Копья{/link} и темный охотник великого мастерства. Он сын вождя Сен'джина, который отдал жизнь, чтобы племя могло последовать за {link:orcs}орк{/link}ами в новый мир. Вол'джин хранит клятву отца. Он стоит рядом с вождем Орды в Крепости {link:grom-hellscream}Громмаш{/link}а, дает ему советы и говорит за свой народ, пока племя Черного Копья ждет в своей деревне у моря того дня, когда сможет вернуть свои острова.]=],
		},
		{
			title = "Значение",
			text = [=[Через него {link:trolls}тролли{/link} стали подлинным народом {link:horde}Орды{/link}, а не только ее союзниками. Он доказательство того, что Орда, которую создал {link:thrall}Тралл{/link}, — союз свободных народов.]=],
		},
		{
			title = "Клятва вождя Сен'джина",
			text = [=[{link:trolls}Тролли{/link} Черного Копья были изгоями, изгнанными из джунглей и рассеянными по островам Южных морей. Когда буря выбросила флот {link:orcs}орк{/link}ов на их берега, племя билось за свою жизнь с людьми и {link:murlocs}мурлок{/link}ами глубин. {link:thrall}Тралл{/link} сражался рядом с троллями. Их вождя, Сен'джина, схватили мурлоки, и он не вернулся, но он предвидел, что вождь орков приведет его народ к новому дому. Сын погибшего вождя связал племя клятвой с Ордой.]=],
		},
		{
			title = "Острова и предатель",
			text = [=[После войны против Легиона племя Черного Копья поселилось на Островах Эха у побережья {link:durotar}Дуротара{/link}. Их мир был недолгим. Флот {link:kul-tiras}Кул Тирас{/link}а напал на острова, и вождю пришлось проследить, чтобы его народ вывезли, пока {link:horde}Орда{/link} наносила ответный удар по кораблям людей. Затем пришел удар похуже: {link:zalazane}Залазан{/link}, знахарь их собственного племени, обратил свою магию против них. Свободные {link:darkspear-trolls}тролли Черного Копья{/link} бежали на материк и построили там деревню, которую назвали в честь погибшего вождя.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он связал племя Черного Копья клятвой с Ордой после смерти отца.
• Он привел свой народ в {link:kalimdor}Калимдор{/link} и поселил его на Островах Эха.
• Он дает советы вождю Орды в Крепости {link:grom-hellscream}Громмаш{/link}а.
• Он снова и снова предостерегает вождя Орды: не доверяй людям.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[О юности вождя здесь записано мало. Эта запись хранит лишь то, что открывают хроники и его дела.]=],
		},
	},
	chapters = {
		{
			title = "Приказы адмирала",
			hint = "Отнесите приказы мертвого адмирала в Оргриммар.",
			text = [=[Когда в Крепости Тирагард нашли приказы адмирала {link:daelin-proudmoore}Делин{/link}а Праудмура, они в конце концов попали в {link:grommash-hold}Крепость Громмаша{/link}, где их принял Вол'джин. Он прочел их и не удивился. Он давно убеждал вождя Орды не доверять людям, и замыслы адмирала доказали его правоту. Злорадствовать он не стал. Он тотчас пошел держать совет с вождем.]=],
		},
		{
			title = "Мастер порчи",
			hint = "Сразите знахаря, который держит Острова Эха.",
			text = [=[Весть о том, что {link:zalazane}Залазан{/link} пал, пришла в {link:orgrimmar}Оргриммар{/link} из Деревни Сен'джин. Для вождя племени Черного Копья это было малое утешение. Проклятие предателя все еще лежит на островах, и многие из его народа все еще бродят там с пустым разумом. День возвращения племени домой еще не настал.]=],
		},
	},
	mentions = {
		{ text = "Приказы адмирала" },
		{
			text = [=[{link:zalazane}Залазан{/link}, убитый по просьбе мастера Гадрина]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Тралл", note = "его вождь" },
		{ id = "zalazane", name = "Залазан", note = "предатель его племени" },
		{ id = "master-gadrin", name = "Мастер Гадрин", note = "старейшина его народа" },
		{ id = "eitrigg", name = "Эйтригг", note = "такой же советник" },
	},
})

Translate("ruRU", "eitrigg", {
	title = "Эйтригг",
	subtitle = "Советник вождя",
	found = "Крепость Громмаша",
	hint = [=[Поговорите со старым воином, который дает советы вождю в Крепости Громмаша.]=],
	allegiance = "Орда · Клан Черной горы (в прошлом)",
	sections = {
		{
			title = "Обзор",
			text = [=[Эйтригг — старый воин-{link:orcs}орк{/link} клана Черной горы, который служит вождю Орды советником и надзирает за ее новобранцами. Он сражался в войнах старой Орды под началом двух вождей — Чернорука и Молота Рока. Он возненавидел поклонников демонов, сбивших его народ с пути, и на время вовсе покинул Орду. Он вернулся, когда услышал, какой видит Орду {link:thrall}Тралл{/link}: ведомой шаманами, а не демонами.]=],
		},
		{
			title = "Значение",
			text = [=[Эйтригг — мост между старой Ордой и новой. Обычаи клана Черной горы он знает лучше любого {link:orcs}орк{/link}а в {link:orgrimmar}Оргриммар{/link}е, и он знает, чего стоит их оставить.]=],
		},
		{
			title = "Деяния",
			text = [=[• Во дни до {link:dark-portal}Темного портала{/link} он служил помощником вождя клана Черной горы, вместе с воином {link:orgrim-doomhammer}Оргрим{/link}ом Молотом Рока.
• Во время {link:second-war}Второй войны{/link} он стерег убийцу Гарону и отпустил ее, когда она бежала.
• Он покинул Орду и ушел на север, в земли людей, где его взяли в плен, а спас его вождь.
• Он надзирает за обучением новобранцев для вождя.]=],
		},
	},
	chapters = {
		{
			title = "Ренд жив",
			hint = "Принесите советнику весть о клане Черной горы.",
			text = [=[Весть пришла из Бесплодных земель: Ренд Чернорук, сын старого вождя Чернорука, жив и собирает {link:blackrock-clan}клан Черной горы{/link} на Вершине Черной горы. Считалось, что он давно убит. Никто в {link:orgrimmar}Оргриммар{/link}е не знал клан Черной горы так, как Эйтригг, и ни у кого не было больше прав на месть. Он передал весть вождю.]=],
		},
		{
			title = "Голова самозванца",
			hint = "Принесите вождю голову орка Ренда Чернорука.",
			text = [=[Когда голову самозванца положили перед вождем, Эйтригг увидел, как сломлена последняя тень клана, которому он некогда служил. {link:blackrock-clan}Клан Черной горы{/link} вновь п{link:ogres}огр{/link}узился в хаос. Для старого воина это был уплаченный долг.]=],
		},
	},
	mentions = {
		{ text = "Новая {link:horde}Орда{/link}" },
		{ text = "Мудрость советника Эйтригга" },
		{ text = "За Орду!" },
	},
	bonds = {
		{ id = "thrall", name = "Тралл", note = "его вождь и спаситель" },
		{ id = "orgrim-doomhammer", name = "Оргрим Молот Рока", note = "его старый товарищ" },
		{ id = "vol-jin", name = "Вол'джин", note = "такой же советник" },
		{ id = "tirion-fordring", name = "Тирион Фордринг", note = "человек, который его спас" },
	},
})

Translate("ruRU", "neeru-fireblade", {
	title = "Ниру Огненный Клинок",
	subtitle = "Чернокнижник Расселины Теней",
	found = "Его шатер в Расселине Теней",
	hint = "Ищите чернокнижника, чей шатер стоит в Расселине Теней.",
	allegiance = "Орда (на словах)",
	aliases = { "Ниру" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ниру Огненный Клинок — чернокнижник, живущий в Расселине Теней. Мало кто из {link:orcs}орк{/link}ов доверяет таким, как он, ибо именно чернокнижники первыми связали орков с демонами. Ниру уверяет, что пользуется своим искусством только против демонов. После последней войны, говорит он, он выискивает каждый след демонической порчи в обществе орков и служит вождю, искореняя секты, что прячутся в его городе.]=],
		},
		{
			title = "Значение",
			text = [=[Ниру стоит в средоточии борьбы против {link:burning-blade}Пылающего Клинка{/link}. Каждая нить этой секты в {link:durotar}Дуротар{/link}е, похоже, ведет обратно в Расселину Теней.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он изучает обжигающие ошейники Пылающего Клинка.
• Он приказывает уничтожить Семя Демона, предмет демонической силы, на Вершине Багрового Тумана в {link:the-barrens}Степях{/link}.
• Он посылает героев в Огненную пропасть убить стража Скверны {link:taragaman-the-hungerer}Тарагаман{/link}а.
• Он торгует травами со знахарем {link:feralas}Фераласа{/link}, которого зовут {link:witch-doctor-uzer-i}Узер'и{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Обжигающий ошейник",
			hint = [=[Принесите обжигающий ошейник от орка Маргоза в Расселину Теней.]=],
			text = [=[Когда {link:margoz}Маргоз{/link} прислал ему обжигающий ошейник, Ниру внимательно его осмотрел. Он назвал секту, которая его сделала, — {link:burning-blade}Пылающий Клинок{/link} — и предмет силы, вокруг которого она сплачивается: Семя Демона. Он хотел, чтобы его уничтожили.]=],
		},
		{
			title = "Семя Демона",
			hint = "Уничтожьте Семя Демона на Вершине Багрового Тумана.",
			text = [=[Помощник чернокнижника, Ак'Зелот, приготовил камни, чтобы разорвать связь Семени с Легионом. Когда Семя было уничтожено, по эфиру прошли волны силы. Ак'Зелот почувствовал их и предупредил, что их почувствовали и другие.]=],
		},
		{
			title = "Истинная верность",
			hint = "Узнайте, что вождю известно о чернокнижнике.",
			text = [=[Ниру — тайный предводитель Пылающего Клинка и слуга {link:shadow-council}Совета Теней{/link}. Он считает вождя глупцом, который ему доверяет. Он ошибается: вождь знает и оставляет его в живых, потому что он полезен. Ниру посылает верных сторонников вождя умирать в Огненной пропасти и испытывает секту Палящего Клинка, чтобы увидеть, кто из ее членов достоин. Когда молодой лейтенант Клинка пришел к нему с нужным знаком, Ниру принял у себя лазутчика.]=],
		},
		{
			title = "Ненасытный",
			hint = "Убейте стража Скверны, который ведет секту Палящего Клинка.",
			text = [=[Ниру назвал хозяином секты Палящего Клинка стража Скверны {link:taragaman-the-hungerer}Тарагаман{/link}а Ненасытного и попросил его сердце — в угоду вождю. Секта Палящего Клинка была для него расходным материалом. Значение имели лишь двое из ее предводителей, и страж Скверны к ним не относился.]=],
		},
	},
	mentions = {
		{ text = "Ниру Огненный Клинок" },
		{ text = "Пылающие тени" },
		{ text = "Ак'Зелот" },
		{ text = "Семя Демона" },
		{ text = "Скрытые враги" },
		{ text = "Убить зверя" },
		{ text = "Странная просьба" },
	},
	bonds = {
		{ id = "thrall", name = "Тралл", note = "вождь, который за ним следит" },
		{ id = "margoz", name = "Маргоз", note = "прислал ему ошейник" },
		{ id = "gazz-uz", name = "Газз'уз", note = "слуга Клинка" },
		{ id = "taragaman-the-hungerer", name = "Тарагаман Ненасытный", note = "страж Скверны, которого он выдал" },
	},
})

