Translate("ruRU", "kor-ghan", {
	title = "Кор'ган",
	subtitle = "Отравитель из ущелья",
	found = "Расселина Теней",
	hint = "Найдите тролля-отравителя в Расселине Теней.",
	allegiance = "Племя Черного Копья",
	sections = {
		{
			title = "Обзор",
			text = [=[Кор'ган — тролль племени Черного Копья, который трудится в Расселине Теней. Он знает яды скорпидов {link:durotar}Дуротар{/link}а и то, как превратить яд скорпида в лекарство от него. Он также суровый знаток обрядов, и те, кто у него учится, должны доказывать свою годность снова и снова. Его ученики жалуются, но остаются в живых.]=],
		},
		{
			title = "Значение",
			text = [=[Кор'ган — тот, кого ищут молодые {link:durotar}Дуротар{/link}а, когда в их крови яд скорпида.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он варит противоядие от яда ядохвоста из ядовитых мешочков самих скорпидов.
